import re

def eval_expression(expr):
    # 1. トークナイズ: 数値、演算子、括弧を分離する
    # \d*\.\d+ : 小数点を含む数値
    # \d+       : 整数
    # [+\-*/()] : 演算子と括弧
    tokens = re.findall(r'\d*\.\d+|\d+|[+\-*/()]', expr)
    pos = 0

    def peek():
        """現在のトークンを覗き見る"""
        nonlocal pos
        return tokens[pos] if pos < len(tokens) else None

    def consume():
        """現在のトークンを消費して次に進む"""
        nonlocal pos
        token = peek()
        pos += 1
        return token

    def parse_expression():
        """加算と減算を処理 (優先度 最低)"""
        node = parse_term()
        while peek() in ('+', '-'):
            op = consume()
            right = parse_term()
            if op == '+':
                node += right
            else:
                node -= right
        return node

    def parse_term():
        """乗算と除算を処理 (優先度 中)"""
        node = parse_factor()
        while peek() in ('*', '/'):
            op = consume()
            right = parse_factor()
            if op == '*':
                node *= right
            else:
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                node /= right
        return node

    def parse_factor():
        """単項演算子(負の数)と括弧、数値を処理 (優先度 最高)"""
        token = peek()

        # 負の数の処理 (単項マイナス)
        if token == '-':
            consume()
            return -parse_factor()

        # 正の数の符号がある場合 (例: +5)
        if token == '+':
            consume()
            return parse_factor()

        # 括弧の処理
        if token == '(':
            consume() # '(' を消費
            result = parse_expression()
            if peek() == ')':
                consume() # ')' を消費
            return result

        # 数値の処理
        token = consume()
        if token is None:
            raise ValueError("Unexpected end of expression")
        return float(token)

    # 計算開始
    try:
        result = parse_expression()
        # 結果が整数（.0）なら整数型で返す
        return int(result) if result.is_integer() else result
    except (IndexError, ValueError) as e:
        raise ValueError(f"Invalid expression: {expr}") from e

# --- テストケース ---
if __name__ == "__main__":
    test_cases = [
        ("3 + 4 * (2 - 1)", 7),
        ("-3 + 4", 1),
        ("10 / 2 + 3", 8),
        ("2 * (3 + 4) * 2", 28),
        ("-5 * (-2 + 3)", -5),
        ("10 / 4", 2.5),
        ("10 / 0", ZeroDivisionError),
    ]

    for expr, expected in test_cases:
        try:
            res = eval_expression(expr)
            print(f"'{expr}' => {res} (Expected: {expected})")
        except ZeroDivisionError:
            print(f"'{expr}' => ZeroDivisionError (Expected: {expected})")
        except Exception as e:
            print(f"'{expr}' => Error: {e}")
